package com.moishow.identity;
import org.springframework.context.annotation.Profile;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
import java.time.Instant;import java.util.*;
@RestController @Profile("db") @RequestMapping("/api/v1")
class FinanceController {
 final Commands commands;final FinanceService service;FinanceController(Commands commands,FinanceService service){this.commands=commands;this.service=service;}
 record Delta(UUID userId,Long amount){}
 record Allocation(UUID roundId,String kind,Long amount){}
 record Funding(UUID paidByUserId,String source,Long amount,Instant actualPaidAt){}
 record Form(Long version,String mode,Long amount,Instant deadline,UUID requestId,String evidence,Instant actualReceivedAt,String reason,UUID roundId,String title,UUID userId,String status,List<Delta> adjustments,String transactionReference,List<Allocation> allocations,Instant actualSentAt,UUID revisionId,Long correctionAmount,String publicResult,UUID participationId,Long agreedFee,Long feeVersion,UUID paidByUserId,List<Funding> fundings,UUID cashAccountId){}
 @GetMapping("/events/{id}/finance") Object get(@AuthenticationPrincipal Actor a,@PathVariable UUID id){return service.get(a,id);}
 @GetMapping("/events/{id}/finance/disputes/{disputeId}") Object dispute(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable UUID disputeId){return service.disputeDetail(a,id,disputeId);}
 @PostMapping("/events/{id}/finance/{action}") Object post(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Form f){return commands.run(a,"finance:"+id+":"+action,key,f,()->switch(action){case "open"->service.open(a,id,f);case "late-fees"->service.lateFees(a,id,f);case "reports"->service.report(a,id,f);case "expenses"->service.expense(a,id,f);case "register","close"->service.register(a,id,action,f);case "revisions"->service.revise(a,id,f);case "refunds"->service.refund(a,id,f);case "disputes"->service.dispute(a,id,f);default->throw new ApiProblem(404,"UNKNOWN_OPERATION");});}
 @PostMapping("/rounds/{id}/payment-requests") Object requests(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Form f){return commands.run(a,"finance:round:"+id,key,f,()->service.request(a,id,f));}
 @PostMapping("/rounds/{id}/billing/close") Object closeRound(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Form f){return commands.run(a,"finance:close-round:"+id,key,f,()->service.closeRound(a,id,f));}
 @PostMapping("/events/{id}/finance/{kind}/{child}/{action}") Object child(@AuthenticationPrincipal Actor a,@PathVariable UUID id,@PathVariable String kind,@PathVariable UUID child,@PathVariable String action,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Form f){return commands.run(a,"finance:"+id+":"+kind+":"+child+":"+action,key,f,()->{if(kind.equals("expenses")&&action.equals("classify"))return service.classifyExpense(a,id,child,f);if(kind.equals("requests")&&action.equals("extend"))return service.extend(a,id,child,f);if(kind.equals("reports")&&action.equals("correct"))return service.correctReceipt(a,id,child,f);if(kind.equals("reports"))return service.verify(a,id,child,action,f);if(kind.equals("participations")&&action.equals("correct"))return service.correctParticipation(a,id,child,f);if(kind.equals("refunds")&&action.equals("sent"))return service.sent(a,id,child,f);if(kind.equals("disputes")&&action.equals("review"))return service.review(a,id,child,f);if(kind.equals("refunds")&&action.equals("confirm"))return service.confirm(a,id,child,f);if(kind.equals("disputes")&&action.equals("resolve"))return service.resolve(a,id,child,f);throw new ApiProblem(404,"UNKNOWN_OPERATION");});}
}
